import{c as a,Q as t,j as r,m as s}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Security & Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"help/security.md","filePath":"help/security.md","lastUpdated":null}'),i={name:"help/security.md"};function o(n,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="security-privacy" tabindex="-1">Security &amp; Privacy <a class="header-anchor" href="#security-privacy" aria-label="Permalink to &quot;Security &amp; Privacy&quot;">​</a></h1><p>This page states what the implementation actually does. Claims are grounded in <code>crate/finsight-server::crypto.rs</code>, <code>sessions.rs</code>, <code>users.rs</code>, and <code>README</code>.</p><h2 id="data-at-rest" tabindex="-1">Data at rest <a class="header-anchor" href="#data-at-rest" aria-label="Permalink to &quot;Data at rest&quot;">​</a></h2><ul><li>Each user’s ledger is a <strong>SQLCipher-encrypted</strong> database (<code>users/&lt;uuid&gt;/data.sqlcipher</code>) with a <strong>random 32-byte key</strong> per user.</li><li>The key is stored only <strong>wrapped</strong>, twice: <ul><li><code>Wrap(Argon2id(password, kek_salt))</code> — Argon2id pinned at m=19456 KiB, t=2, p=1, id v19</li><li><code>Wrap(recovery_key_bytes)</code> — the printable recovery key is the KEK directly (high-entropy, no KDF)</li></ul></li><li>Password verification uses a <strong>separate</strong> Argon2id PHC string (own salt) so the verifier cannot derive the KEK.</li><li><code>users.db</code> is <strong>plain SQLite</strong> — it must be readable before unwrapping. It holds usernames, Argon2id verifiers, wrapped keys, and hashed sessions — no financial records, plaintext passwords, or plaintext DB keys.</li><li>Unwrapped keys exist <strong>only in server memory</strong>, single-flighted, evicted after 30 minutes idle unless an SSE client is attached.</li></ul><h2 id="data-in-transit-sessions" tabindex="-1">Data in transit &amp; sessions <a class="header-anchor" href="#data-in-transit-sessions" aria-label="Permalink to &quot;Data in transit &amp; sessions&quot;">​</a></h2><ul><li>Session cookies are <code>HttpOnly</code>, <code>SameSite=Lax</code>, sliding 30-day lifetime. <code>FINSIGHT_COOKIE_SECURE=1</code> adds <code>Secure</code> — required behind HTTPS (Tailscale/Caddy); set <code>0</code> only for bare-HTTP LAN tests.</li><li>The cookie token is stored on the client; <code>users.db</code> holds its <strong>hash</strong> and a DB key wrapped by <code>/data/session.key</code> (persisted sessions survive restarts).</li><li>Logout, recovery, deletion, and “sign out other devices” revoke the persisted rows.</li></ul><h2 id="attack-surface" tabindex="-1">Attack surface <a class="header-anchor" href="#attack-surface" aria-label="Permalink to &quot;Attack surface&quot;">​</a></h2><ul><li><strong>Docker</strong>: <code>read_only: true</code>, <code>no-new-privileges:true</code>, <code>cap_drop: ALL</code>, only <code>/data</code> and a small <code>tmpfs</code> writable.</li><li><strong>Browser cache</strong>: seven-day, read-only IndexedDB query cache, encrypted when the PWA has a secure context; purged on logout. It is a convenience, not the vault.</li><li><strong>When data leaves your server</strong>: only on opt-in integrations — cloud AI (redacted context) and SimpleFIN (access URL exchange). See <a href="/FinSight/getting-started/privacy">Privacy &amp; Local Data</a> for the table.</li></ul><h2 id="what-is-not-claimed" tabindex="-1">What is not claimed <a class="header-anchor" href="#what-is-not-claimed" aria-label="Permalink to &quot;What is not claimed&quot;">​</a></h2><ul><li>Not end-to-end (browser↔server) encryption of ledger — the server must hold the unwrapped DB key in memory to serve your session.</li><li>Not zero-knowledge browser cache — assume anyone with a usable session and device can read what the cache holds.</li><li><code>users.db</code> is not encrypted; protect <code>/data/session.key</code> and <code>/data</code> file permissions (owner-only on the host).</li></ul><h2 id="ops-hardening" tabindex="-1">Ops hardening <a class="header-anchor" href="#ops-hardening" aria-label="Permalink to &quot;Ops hardening&quot;">​</a></h2><ul><li>Strong, unique passwords (≥10 chars enforced) + 60s throttle after 5 failures per username.</li><li>Keep <code>FINSIGHT_COOKIE_SECURE=1</code> behind HTTPS; never leave <code>0</code> on an internet-reachable origin.</li><li>Put the server behind HTTPS (see <a href="/FinSight/help/self-hosting">Self-Hosting</a>) and consider fail2ban for internet-facing deploys.</li></ul><p>See also: <a href="/FinSight/configuration/data-storage">Data Storage</a>, <a href="/FinSight/getting-started/privacy">Getting Started → Privacy</a>.</p>',13)])])}const g=a(i,[["render",o]]);export{p as __pageData,g as default};
